package it.frociart.app;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;import android.view.*;import java.util.*;
/** Event-driven drawing: no polling while idle, no copy of the drawing for every frame. */
final class FlowTurtleView extends View {
 private Bitmap cache,ghost;private double[] cacheBounds,ghostBounds;private long cacheRevision=-2;
 private final Paint paint=new Paint(3);private FlowTurtle turtle;private long revision=-1,started;private int count;private boolean tail;
 private double x,y,angle=90,fromX,fromY,fromAngle=90;private double[] bounds={0,0,100,100},fromBounds=bounds.clone();private double zoom=1,fromZoom=1,panX,panY,fromPanX,fromPanY;private float touchX,touchY;private final ScaleGestureDetector scaleGesture;
 FlowTurtleView(Context c){super(c);setBackgroundColor(Color.WHITE);setFocusable(true);setContentDescription("Disegno della tartaruga. Trascina per spostare, pizzica per zoom. Usa Tutto per vedere il disegno completo.");scaleGesture=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector detector){zoom(detector.getScaleFactor());return true;}});}
 private double progress(){return started==0||!Ui.animations()?1:Math.min(1,(SystemClock.uptimeMillis()-started)/280d);}
 private double spring(){return Ui.spring((float)progress());}private static double mix(double a,double b,double t){return a+(b-a)*t;}
 private void sample(){double p=spring(),clamped=Math.max(0,Math.min(1,p));fromX=mix(fromX,x,clamped);fromY=mix(fromY,y,clamped);fromAngle=mix(fromAngle,angle,p);for(int i=0;i<4;i++)fromBounds[i]=mix(fromBounds[i],bounds[i],p);fromZoom=mix(fromZoom,zoom,p);fromPanX=mix(fromPanX,panX,p);fromPanY=mix(fromPanY,panY,p);}
 private void animateChange(){started=Ui.animations()&&isAttachedToWindow()?SystemClock.uptimeMillis():0;invalidate();}
 void bind(FlowTurtle next){if(turtle==next&&revision==(next==null?-1:next.revision()))return;if(ghost!=null){ghost.recycle();ghost=null;}if(turtle==next&&next!=null&&next.segments().size()<count&&Ui.animations()&&cache!=null){ghost=cache;ghostBounds=cacheBounds;cache=null;}sample();boolean same=turtle==next;tail=same&&next!=null&&next.segments().size()==count+1;turtle=next;revision=next==null?-1:next.revision();count=next==null?0:next.segments().size();x=next==null?0:next.x();y=next==null?0:next.y();double a=next==null?90:next.heading();angle=fromAngle+((a-fromAngle+540)%360+360)%360-180;bounds=sceneBounds(next==null?Collections.emptyList():next.segments(),x,y);if(!same){cacheRevision=-2;fromX=x;fromY=y;fromAngle=angle;fromBounds=bounds.clone();zoom=fromZoom=1;panX=panY=fromPanX=fromPanY=0;}animateChange();}
 void fit(){sample();zoom=1;panX=panY=0;if(tail)cacheRevision=-2;tail=false;animateChange();}void zoom(double factor){sample();zoom=Math.max(.1,Math.min(40,zoom*factor));if(tail)cacheRevision=-2;tail=false;animateChange();}
 static double[] sceneBounds(List<FlowTurtle.Segment> lines,double x,double y){double minX=Math.min(0,x),maxX=Math.max(0,x),minY=Math.min(0,y),maxY=Math.max(0,y);for(FlowTurtle.Segment s:lines){minX=Math.min(minX,Math.min(s.x1,s.x2));maxX=Math.max(maxX,Math.max(s.x1,s.x2));minY=Math.min(minY,Math.min(s.y1,s.y2));maxY=Math.max(maxY,Math.max(s.y1,s.y2));}return new double[]{(minX+maxX)/2,(minY+maxY)/2,Math.max(100,maxX-minX),Math.max(100,maxY-minY)};}
 @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);if(getWidth()<1||getHeight()<1)return;double p=spring(),bounded=Math.max(0,Math.min(1,p));double[] view=new double[4];for(int i=0;i<4;i++)view[i]=mix(fromBounds[i],bounds[i],p);view[2]=Math.max(1,view[2]);view[3]=Math.max(1,view[3]);List<FlowTurtle.Segment> lines=turtle==null?Collections.emptyList():turtle.segments();float density=getResources().getDisplayMetrics().density;int w=Math.min(1600,getWidth()),h=Math.min(1200,getHeight());
  if(cache==null||cacheRevision!=revision||cache.getWidth()!=w||cache.getHeight()!=h){if(cache!=null)cache.recycle();cache=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);cacheBounds=bounds.clone();drawScene(new Canvas(cache),w,h,lines,cacheBounds,x,y,angle,tail?0:1,1,0,0,false,density,paint,true);cacheRevision=revision;}
  double z=mix(fromZoom,zoom,p),px=mix(fromPanX,panX,p),py=mix(fromPanY,panY,p);canvas.drawColor(Color.WHITE);drawCached(canvas,cache,cacheBounds,view,z,px,py,density,255);
  List<FlowTurtle.Segment> last=tail&&!lines.isEmpty()?Collections.singletonList(lines.get(lines.size()-1)):Collections.emptyList();drawScene(canvas,getWidth(),getHeight(),last,view,mix(fromX,x,p),mix(fromY,y,p),mix(fromAngle,angle,p),bounded,z,px,py,true,density,paint,false);
  if(ghost!=null){if(progress()>=1){ghost.recycle();ghost=null;}else drawCached(canvas,ghost,ghostBounds,view,z,px,py,density,(int)(255*(1-bounded)));}if(progress()<1&&isAttachedToWindow())postInvalidateOnAnimation();
 }
 private void drawCached(Canvas canvas,Bitmap image,double[] source,double[] view,double zoom,double px,double py,float density,int alpha){double scale=Math.max(.000001,Math.min(Math.max(1,getWidth()-54*density)/view[2],Math.max(1,getHeight()-54*density)/view[3]))*zoom,sourceScale=Math.max(.000001,Math.min(Math.max(1,image.getWidth()-54*density)/source[2],Math.max(1,image.getHeight()-54*density)/source[3])),ratio=scale/sourceScale;float x=(float)(getWidth()/2d+(source[0]-view[0])*scale+px-image.getWidth()*ratio/2),y=(float)(getHeight()/2d-(source[1]-view[1])*scale+py-image.getHeight()*ratio/2);paint.setAlpha(alpha);paint.setFilterBitmap(true);canvas.drawBitmap(image,null,new RectF(x,y,x+(float)(image.getWidth()*ratio),y+(float)(image.getHeight()*ratio)),paint);paint.setAlpha(255);}
 static void drawScene(Canvas canvas,int width,int height,List<FlowTurtle.Segment> lines,double[] b,double x,double y,double angle,double tail,double zoom,double panX,double panY,boolean cursor,float density,Paint p,boolean clear){if(clear)canvas.drawColor(Color.WHITE);double scale=Math.max(.000001,Math.min(Math.max(1,width-54*density)/b[2],Math.max(1,height-54*density)/b[3]))*zoom;double ox=width/2d-b[0]*scale+panX,oy=height/2d+b[1]*scale+panY;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2*density);p.setStrokeCap(Paint.Cap.ROUND);String previous=null;for(int i=0;i<lines.size();i++){FlowTurtle.Segment s=lines.get(i);if(!s.color.equals(previous)){p.setColor(Color.parseColor(s.color));previous=s.color;}double t=i==lines.size()-1?tail:1;canvas.drawLine((float)(ox+s.x1*scale),(float)(oy-s.y1*scale),(float)(ox+(s.x1+(s.x2-s.x1)*t)*scale),(float)(oy-(s.y1+(s.y2-s.y1)*t)*scale),p);}
  if(cursor){double a=angle*Math.PI/180;Path path=new Path();for(int i=0;i<3;i++){double heading=a+(i==0?0:i==1?2.5:-2.5);float px=(float)(ox+x*scale+Math.cos(heading)*10*density),py=(float)(oy-y*scale-Math.sin(heading)*10*density);if(i==0)path.moveTo(px,py);else path.lineTo(px,py);}path.close();p.setStyle(Paint.Style.FILL);p.setColor(0xff5085f0);canvas.drawPath(path,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.4f*density);p.setColor(0xff223450);canvas.drawPath(path,p);}
 }
 static Bitmap render(FlowTurtle.Snapshot s,int width,int height){if(width<64||height<64||width>4096||height>4096)throw new IllegalArgumentException("Dimensioni immagine non valide.");Bitmap b=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);drawScene(new Canvas(b),width,height,s.segments,sceneBounds(s.segments,s.x,s.y),s.x,s.y,s.heading,1,1,0,0,false,1,new Paint(3),true);return b;}
 @Override public boolean onTouchEvent(MotionEvent e){scaleGesture.onTouchEvent(e);switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:touchX=e.getX();touchY=e.getY();getParent().requestDisallowInterceptTouchEvent(true);return true;case MotionEvent.ACTION_MOVE:if(!scaleGesture.isInProgress()&&e.getPointerCount()==1){sample();panX+=e.getX()-touchX;panY+=e.getY()-touchY;fromPanX=panX;fromPanY=panY;invalidate();}touchX=e.getX();touchY=e.getY();return true;case MotionEvent.ACTION_UP:performClick();case MotionEvent.ACTION_CANCEL:getParent().requestDisallowInterceptTouchEvent(false);return true;default:return true;}}
 @Override public boolean performClick(){super.performClick();return true;}@Override protected void onDetachedFromWindow(){started=0;if(cache!=null){cache.recycle();cache=null;}if(ghost!=null){ghost.recycle();ghost=null;}super.onDetachedFromWindow();}
}
